/**
 * Penempatan mesh statis hasil ekspor glTF (format generator gltfjsx) yang
 * semula inline di Model.tsx. Satu entri = satu <mesh>: geometri dari
 * nodes[g], material dari materials[m], plus posisi/rotasi/scale verbatim
 * dari ekspor asli.
 *
 * Urutan array = urutan render — JANGAN diurutkan ulang atau disisipi.
 */
export type MeshPart = {
  /** Nama node geometri di glTF (nodes['...']). */
  g: string
  /** Kunci material di glTF (materials['...']). */
  m: string
  p: [number, number, number]
  r?: [number, number, number]
  s?: number
}

